t(BY.text(text), message, timeout=timeout)\r\n\r\n    def require_type(self, component_type: str, message: str, timeout: float = DEFAULT_TIMEOUT):\r\n        \"\"\"查找指定类型（如 'List'、'Slider'、'Toggle'）的组件。\"\"\"\r\n        return self.require_component(BY.type(component_type), message, timeout=timeout)\r\n\r\n    def require_precondition(self, condition: bool, message: str) -> None:\r\n        \"\"\"前置条件不满足时记为 skip（未验证），而不是通过或失败。\"\"\"\r\n        if not condition:\r\n            self.skipTest(f\"前置条件未满足: {message}\")\r\n\r\n    @staticmethod\r\n    def slider_value(slider) -> float:\r\n        \"\"\"读取 Slider 当前值（UI dump 里 Slider 的 text 即其数值，如 '18.000000'）。\"\"\"\r\n        return float(slider.getText())\r\n\r\n    def sliders(self) -> list:\r\n        \"\"\"当前页面所有 Slider，按页面从上到下的顺序。\"\"\"\r\n        return self.driver.find_all_components(BY.type(\"Slider\")) or []\r\n\r\n    def set_slider(self, index: int, value: float, vmin: float, vmax: float,\r\n                   tolerance: float | None = None, attempts: int = 3) -> float:\r\n        \"\"\"点击第 index 个 Slider 轨道上对应 value 的位置，返回最终读到的实际值。\r\n\r\n        实测（HarmonyOS 6.1 模拟器）：点击轨道会直接跳值，轨道铺满组件 bounds，位置与数值线性对应；\r\n        刚进入页面后的第一次点击观察到被丢弃过一次，所以读回值与目标不符时会重试。\r\n        实际值取决于被测 Slider 的 step：返回值不等于 value 不代表 harness 出错，\r\n        可能正是被测应用的 Slider 取不到该值，调用方应对返回值做断言。\r\n        \"\"\"\r\n        tol = tolerance if tolerance is not None else (vmax - vmin) * 0.02\r\n        actual = self.slider_value(self.sliders()[index])\r\n        for _ in range(attempts):\r\n            b = self.sliders()[index].getBounds()\r\n            frac = (value - vmin) / (vmax - vmin)\r\n            x = min(max(int(b.left + frac * (b.right - b.left)), b.left + 2), b.right - 2)\r\n            self.driver.click((x, (b.top + b.bottom) // 2))\r\n            self.driver.wait(0.8)\r\n            actual = self.slider_value(self.sliders()[index])\r\n            if abs(actual - value) <= tol:\r\n                break\r\n        return actual\r\n\r\n    def text_after(self, label: str) -> str | None:\r\n        \"\"\"页面文本序列里紧跟在 label 之后的那一项（用于读取“标题 + 数值”形式的行）。\"\"\"\r\n        texts = [t.getText() for t in (self.driver.find_all_components(BY.type(\"Text\")) or [])]\r\n        texts = [t for t in texts if t]\r\n        return texts[texts.index(label) + 1] if label in texts else None\r\n"}
{"Path":"../common/test-harness/harness/runner.py","Content":"\"\"\"测试运行器：发现并执行某道题目录下的测试文件，汇总统一格式的报告。\r\n\r\n用法：\r\n    python -m harness.runner --project <本题工程目录> [--device <序列号>] [--json out.json]\r\n\r\n约定：被测项目目录下的 `hypium_tests/test_*.py` 为该题的测试文件，\r\n其中的测试类应继承 `harness.driver.HarnessTestCase`。\r\n\"\"\"\r\nfrom __future__ import annotations\r\n\r\nimport argparse\r\nimport sys\r\nimport unittest\r\nfrom pathlib import Path\r\n\r\nfrom . import device as device_mod\r\nfrom . import env_check\r\nfrom .report import RecordingResult, RunReport\r\n\r\n\r\ndef discover(project_dir: Path) -> unittest.TestSuite:\r\n    tests_dir = project_dir / \"hypium_tests\"\r\n    if not tests_dir.is_dir():\r\n        raise FileNotFoundError(\r\n            f\"未找到测试目录: {tests_dir}；请在该题工作目录下创建 hypium_tests/test_*.py\"\r\n        )\r\n    loader = unittest.TestLoader()\r\n    return loader.discover(start_dir=str(tests_dir), pattern=\"test_*.py\", top_level_dir=str(project_dir))\r\n\r\n\r\ndef _collect_case_names(suite: unittest.TestSuite) -> list[str]:\r\n    names = []\r\n    for test in suite:\r\n        if isinstance(test, unittest.TestSuite):\r\n            names.extend(_collect_case_names(test))\r\n        else:\r\n            names.append(str(test))\r\n    return names\r\n\r\n\r\ndef _inject_device_sn(suite: unittest.TestSuite, device_sn: str) -> None:\r\n    \"\"\"把设备序列号注入每个 HarnessTestCase 子类，供 setUpClass 使用。\"\"\"\r\n    for test in suite:\r\n        if isinstance(test, unittest.TestSuite):\r\n            _inject_device_sn(test, device_sn)\r\n        else:\r\n            test.__class__.device_sn = device_sn\r\n\r\n\r\ndef main(argv: list[str] | None = None) -> int:\r\n    parser = argparse.ArgumentParser(description=__doc__)\r\n    parser.add_argument(\"--project\", required=True, help=\"本题工程目录（绝对路径）\")\r\n    parser.add_argument(\"--device\", default=None, help=\"设备序列号，省略则要求唯一在线设备\")\r\n    parser.add_argument(\"--json\", default=None, help=\"将报告另存为 JSON 文件的路径\")\r\n    parser.add_argument(\"--skip-env-check\", action=\"store_true\", help=\"跳过环境规格校验\")\r\n    args = parser.parse_args(argv)\r\n\r\n    project_dir = Path(args.project).resolve()\r\n    device_sn = device_mod.select_device(args.device)\r\n\r\n    env_warnings: list[str] = []\r\n    if not args.skip_env_check:\r\n        env_warnings = env_check.check(device_sn).warnings\r\n\r\n    suite = discover(project_dir)\r\n    case_names = _collect_case_names(suite)\r\n    _inject_device_sn(suite, device_sn)\r\n\r\n    runner = unittest.TextTestRunner(verbosity=2, resultclass=RecordingResult)\r\n    result = runner.run(suite)\r\n\r\n    report = RunReport(\r\n        project=str(project_dir),\r\n        device_sn=device_sn,\r\n        env_warnings=env_warnings,\r\n        cases=result.to_cases(case_names),\r\n    )\r\n    report.print_summary()\r\n\r\n    if args.json:\r\n        Path(args.json).write_text(report.to_json(), encoding=\"utf-8\")\r\n        print(f\"\\n报告已保存: {args.json}\")\r\n\r\n    return 0 if report.failed == 0 else 1\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    sys.exit(main())\r\n"}
{"Path":"../common/test-harness/harness/device.py","Content":"\"\"\"设备发现与连接：封装 hdc 调用，和题包 Hypium 示例保持一致的选择逻辑。\"\"\"\r\nfrom __future__ import annotations\r\n\r\nimport shutil\r\nimport subprocess\r\n\r\n\r\nclass DeviceError(RuntimeError):\r\n    \"\"\"hdc 不可用、设备数量不符合预期等场景下抛出。\"\"\"\r\n\r\n\r\ndef find_hdc() -> str:\r\n    \"\"\"定位 hdc 可执行文件。要求调用方已将 DevEco SDK 的\r\n    openharmony/toolchains 目录加入 PATH（见 docs/development.md）。\r\n    \"\"\"\r\n    hdc = shutil.which(\"hdc\") or shutil.which(\"hdc_std\")\r\n    if hdc is None:\r\n        raise DeviceError(\r\n            \"未找到 hdc，请将 DevEco Studio 自带的 \"\r\n            \"openharmony/toolchains 目录加入 PATH。\"\r\n        )\r\n    return hdc\r\n\r\n\r\ndef list_targets() -> list[str]:\r\n    \"\"\"返回 `hdc list targets` 报告的已连接设备序列号列表（过滤空槽位）。\"\"\"\r\n    hdc = find_hdc()\r\n    result = subprocess.run(\r\n        [hdc, \"list\", \"targets\"],\r\n        capture_output=True,\r\n        text=True,\r\n        check=True,\r\n        timeout=10,\r\n    )\r\n    return [\r\n        line.strip()\r\n        for line in result.stdout.splitlines()\r\n        if line.strip() and \"[Empty]\" not in line\r\n    ]\r\n\r\n\r\ndef select_device(requested: str | None = None) -> str:\r\n    \"\"\"选定要连接的设备序列号。\r\n\r\n    - 指定了 `requested`：校验它确实在线。\r\n    - 未指定：要求当前只有一台设备在线，否则报错（避免误连错设备）。\r\n    \"\"\"\r\n    devices = list_targets()\r\n    if requested:\r\n        if requested not in devices:\r\n            raise DeviceError(f\"指定设备未连接：{requested}；当前在线设备：{devices}\")\r\n        return requested\r\n    if len(devices) != 1:\r\n        raise DeviceError(\r\n            f\"需要连接恰好一台设备，或通过 --device 明确指定；当前在线设备：{devices}\"\r\n        )\r\n    return devices[0]\r\n\r\n\r\ndef shell(device_sn: str, *args: str, timeout: float = 10) -> str:\r\n    \"\"\"在指定设备上执行一条 `hdc shell` 命令，返回标准输出文本。\"\"\"\r\n    hdc = find_hdc()\r\n    result = subprocess.run(\r\n        [hdc, \"-t\", device_sn, \"shell\", *args],\r\n        capture_output=True,\r\n        text=True,\r\n        check=True,\r\n        timeout=timeout,\r\n    )\r\n    return result.stdout\r\n"}
{"Path":"../common/test-harness/harness/window.py","Content":"\"\"\"窗口几何信息：按窗口名从 hidumper 读取 [x y w h]。\r\n\r\n适用于悬浮窗等不在 UI 树里的窗口。窗口名与 hidumper 输出的首列对应，\r\n行尾可能带数字后缀（如 `cloudmusic0`），这里按“名称 + 可选数字”匹配。\r\n\"\"\"\r\nfrom __future__ import annotations\r\n\r\nimport re\r\nfrom dataclasses import dataclass\r\n\r\nfrom . import device\r\n\r\n\r\n@dataclass(frozen=True)\r\nclass Rect:\r\n    x: int\r\n    y: int\r\n    w: int\r\n    h: int\r\n\r\n    def visible_fraction(self, screen_w: int, screen_h: int) -> float:\r\n        \"\"\"窗口落在屏幕内的面积占窗口总面积的比例，0 表示完全在屏幕外。\"\"\"\r\n        if self.w <= 0 or self.h <= 0:\r\n            return 0.0\r\n        ix = max(0, min(self.x + self.w, screen_w) - max(self.x, 0))\r\n        iy = max(0, min(self.y + self.h, screen_h) - max(self.y, 0))\r\n        return (ix * iy) / (self.w * self.h)\r\n\r\n\r\n# 首列窗口名，其后 8 个数字列（DisplayId Pid WinId Type Mode Flag ZOrd Orientation），再是 [x y w h]\r\n_ROW = r\"^{name}\\d*\\s+(?:-?\\d+\\s+){{8}}\\[\\s*(-?\\d+)\\s+(-?\\d+)\\s+(\\d+)\\s+(\\d+)\\s*\\]\"\r\n\r\n\r\ndef parse_window_rect(dump: str, name: str) -> Rect | None:\r\n    match = re.search(_ROW.format(name=re.escape(name)), dump, re.M)\r\n    if match is None:\r\n        return None\r\n    x, y, w, h = (int(g) for g in match.groups())\r\n    return Rect(x, y, w, h)\r\n\r\n\r\ndef find_window_rect(device_sn: str, name: str) -> Rect | None:\r\n    \"\"\"返回名为 `name` 的窗口当前矩形；窗口不存在时返回 None。\"\"\"\r\n    dump = device.shell(device_sn, \"hidumper\", \"-s\", \"WindowManagerService\", \"-a\", \"-a\")\r\n    return parse_window_rect(dump, name)\r\n"}
