"""统一的测试结果报告格式：终端摘要 + 可选 JSON 文件。

结果分四类：pass / fail / error / skip。
skip 表示“没有被验证”（前置条件不满足、占位用例等），既不算通过也不算失败，
但摘要里会单独列出，避免把未执行的用例误读成绿色。
"""
from __future__ import annotations

import json
import unittest
from dataclasses import asdict, dataclass, field

PASS, FAIL, ERROR, SKIP = "pass", "fail", "error", "skip"
_MARKS = {PASS: "✓", FAIL: "✗", ERROR: "✗", SKIP: "-"}


@dataclass
class CaseResult:
    name: str
    outcome: str  # PASS | FAIL | ERROR | SKIP
    message: str = ""


@dataclass
class RunReport:
    project: str
    device_sn: str
    env_warnings: list[str] = field(default_factory=list)
    cases: list[CaseResult] = field(default_factory=list)

    def _count(self, *outcomes: str) -> int:
        return sum(1 for c in self.cases if c.outcome in outcomes)

    @property
    def passed(self) -> int:
        return self._count(PASS)

    @property
    def failed(self) -> int:
        return self._count(FAIL, ERROR)

    @property
    def skipped(self) -> int:
        return self._count(SKIP)

    def print_summary(self) -> None:
        print(f"\n项目: {self.project}")
        print(f"设备: {self.device_sn}")
        if self.env_warnings:
            print("环境偏差提示:")
            for w in self.env_warnings:
                print(f"  - {w}")
        print(
            f"\n测试用例: {len(self.cases)}  通过: {self.passed}  "
            f"失败: {self.failed}  跳过(未验证): {self.skipped}"
        )
        for c in self.cases:
            print(f"  {_MARKS[c.outcome]} {c.name}" + (f" — {c.message}" if c.message else ""))
        if self.skipped:
            print(f"\n注意: 有 {self.skipped} 个用例被跳过，这些行为没有被验证，不能视为通过。")

    def to_json(self) -> str:
        return json.dumps(asdict(self), ensure_ascii=False, indent=2)


def _last_line(text: str) -> str:
    lines = text.strip().splitlines()
    return lines[-1] if lines else ""


class RecordingResult(unittest.TextTestResult):
    """在 TextTestResult 基础上按用例记录 pass/fail/error/skip。"""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.records: dict[str, CaseResult] = {}

    def _record(self, test, outcome: str, message: str = "") -> None:
        self.records[str(test)] = CaseResult(str(test), outcome, message)

    def addSuccess(self, test):
        super().addSuccess(test)
        self._record(test, PASS)

    def addFailure(self, test, err):
        super().addFailure(test, err)
        self._record(test, FAIL, _last_line(self.failures[-1][1]))

    def addError(self, test, err):
        super().addError(test, err)
        self._record(test, ERROR, _last_line(self.errors[-1][1]))

    def addSkip(self, test, reason):
        super().addSkip(test, reason)
        self._record(test, SKIP, reason)

    def to_cases(self, expected_names: list[str]) -> list[CaseResult]:
        """按发现顺序输出用例结果。

        没有留下记录的用例（所属类 setUpClass 报错或被跳过，导致用例根本没执行）记为 skip；
        setUpClass 自身的报错会作为独立的 error 记录附在末尾，所以不会被漏算成通过。
        """
        cases = [
            self.records.get(name)
            or CaseResult(name, SKIP, "未执行（所属类 setUpClass 出错或被跳过）")
            for name in expected_names
        ]
        cases.extend(r for n, r in self.records.items() if n not in set(expected_names))
        return cases

"""应用生命周期与导航辅助。与具体赛题无关，包名和页面文案由各题测试传入。"""
from __future__ import annotations

import time

from hypium import BY

DEFAULT_TIMEOUT = 15


def restart_app(driver, bundle: str, wait_time: float = 2) -> None:
    """强制停止后冷启动，等价于“完全退出再重新打开”。

    签名取自 Hypium 6.1.0.210（stop_app / start_app），尚未在设备上实测；
    首次使用时请确认 start_app 不带 page_name 时能拉起主 Ability。
    """
    driver.stop_app(bundle)
    driver.start_app(bundle, wait_time=wait_time)


def click_text_path(driver, texts: list[str], timeout: float = DEFAULT_TIMEOUT) -> None:
    """依次点击一串文案，用于从某个起点页逐级导航到目标页。

    每一步都等待目标文案出现；找不到时抛 AssertionError 并指出卡在哪一步。
    """
    for text in texts:
        deadline = time.monotonic() + timeout
        component = None
        while time.monotonic() < deadline:
            component = driver.find_component(BY.text(text))
            if component is not None:
                break
            driver.wait(0.5)
        if component is None:
            raise AssertionError(f"导航失败：{timeout}s 内未找到文案 {text!r}")
        driver.click(component)
        driver.wait(0.5)

"""环境校验：对照 docs/development.md 中"正式评测与自测模拟器配置"一节，
检查当前连接设备的系统版本、屏幕参数是否与官方评测环境一致。

校验结果仅用于提示偏差，不阻塞测试执行——
文档原文强调"本地自测通过不代表正式测试通过"，环境校验的作用是降低偏差，不是替代正式评测。
"""
from __future__ import annotations

import argparse
import re
from dataclasses import dataclass

from . import device

# 官方评测环境规格，来源：docs/development.md 第93-103行"正式评测与自测模拟器配置"
OFFICIAL_SPEC = {
    "model": "Pura 90 Pro Max",
    "config": "PHEMU-FD00",
    "os_version": "6.1.0",
    "api_version": "23",
    "image_version": "6.1.0.115",
    "resolution": (1308, 2880),
    "dpi": 560,
}


@dataclass
class EnvCheckResult:
    device_sn: str
    software_version: str | None
    resolution: tuple[int, int] | None
    warnings: list[str]

    @property
    def matches_official(self) -> bool:
        return not self.warnings


def _get_software_version(device_sn: str) -> str | None:
    try:
        out = device.shell(
            device_sn, "param", "get", "const.product.software.version"
        )
    except Exception:
        return None
    return out.strip() or None


def _get_resolution(device_sn: str) -> tuple[int, int] | None:
    """从 hidumper 的窗口信息里解析屏幕分辨率（取 SCBDesktop/桌面窗口的 w/h）。"""
    try:
        out = device.shell(
            device_sn, "hidumper", "-s", "WindowManagerService", "-a", "-a"
        )
    except Exception:
        return None
    # 形如: "...[ 0    0    1308 2880 ] [ ... ]"，取第一条分辨率合理的记录
    for match in re.finditer(r"\[\s*\d+\s+\d+\s+(\d+)\s+(\d+)\s*\]", out):
        w, h = int(match.group(1)), int(match.group(2))
        if w > 0 and h > 0:
            return (w, h)
    return None


def check(device_sn: str) -> EnvCheckResult:
    warnings: list[str] = []

    software_version = _get_software_version(device_sn)
    if software_version is None:
        warnings.append("无法读取设备系统版本（const.product.software.version）。")
    elif OFFICIAL_SPEC["image_version"] not in software_version:
        warnings.append(
            f"系统镜像版本为 {software_version!r}，"
            f"官方评测使用 {OFFICIAL_SPEC['image_version']}（API {OFFICIAL_SPEC['api_version']}）。"
        )

    resolution = _get_resolution(device_sn)
    if resolution is None:
        warnings.append("无法读取设备屏幕分辨率。")
    elif resolution != OFFICIAL_SPEC["resolution"]:
        warnings.append(
            f"屏幕分辨率为 {resolution}，官方评测使用 "
            f"{OFFICIAL_SPEC['resolution']}（{OFFICIAL_SPEC['model']} / "
            f"{OFFICIAL_SPEC['config']}）。请在 DevEco Studio Device Manager 中确认模拟器机型。"
        )

    return EnvCheckResult(
        device_sn=device_sn,
        software_version=software_version,
        resolution=resolution,
        warnings=warnings,
    )


def _main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--device", default=None, help="设备序列号，省略则要求唯一在线设备")
    args = parser.parse_args()

    device_sn = device.select_device(args.device)
